\begin{theorem}[Quadratic decay]
For $d\ge2$, $I(d)<2/d^2$; for $d\ge3$, $I(d)>-3/d^2$; hence $I(d)\to0$.
\end{theorem}

\begin{theorem}[Sharp rate]\label{thm:rate}
$\displaystyle \lim_{d\to\infty} d^2 I(d)=\log_2 e-1=0.442695\ldots$
\end{theorem}

\begin{proof}[Proof sketch]
Apply the two-sided estimate $\frac{a-b}{a}\le\log\frac ab\le\frac{a-b}{b}$ (both
directions of $\log t\le t-1$) to each of the four logarithms in $d^2I(d)$. This yields,
for $d\ge3$, the envelope
\[
-1+\Bigl(1-\frac{1}{2d}\Bigr)\log_2 e \;\le\; d^2 I(d) \;\le\; -1+\Bigl(1+\frac{1}{d-1}\Bigr)\log_2 e,
\]
whose two ends converge to $\log_2 e - 1$; conclude by squeezing.
\end{proof}

Numerically $d^2I(d)=1.2451,\,0.5741,\,0.5181,\,0.4837,\,0.4463,\,0.4431$ at
$d=2,4,6,10,100,1000$. Hence
\[
I(\ell-1)\sim\frac{\log_2 e-1}{(\ell-1)^2}\ \text{bits}:
\]
the visible half of the dichotomy is itself asymptotically invisible, and the striking
$0.313$ bits at $\ell=3$ is an artefact of $d=2$.

\section{Information versus advantage}

\begin{definition}
Let $s:G\to\mathbb N$ record the number of pairs in the fibre over $n$ on which the event
holds. A \emph{residue-reading predictor} is $f:G\to\{\text{true},\text{false}\}$ with score
\[
\score(f)=\sum_{n\in G}\begin{cases} s(n), & f(n)=\text{true},\\ |G|-s(n), & f(n)=\text{false},\end{cases}
\]
the number of ordered pairs classified correctly out of $|G|^2$.
\end{definition}

\begin{theorem}[Asymmetric: zero advantage]
For every target $A$, no predictor for the asymmetric event scores more than the better of
the two constant predictors.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:asym}, $s\equiv|A|$, so the pointwise optimum
$\max(s(n),|G|-s(n))$ is attained by a constant predictor.
\end{proof}

\begin{theorem}[Symmetric: zero advantage above order three]
Let $A=\{1\}$ and $|G|\ge4$. Then no predictor for the symmetric event scores more than
the constant-false predictor.
\end{theorem}

\begin{proof}[Proof sketch]
Here $s(n)\in\{1,2\}$ while $|G|-s(n)\ge|G|-2\ge2\ge s(n)$, so ``false'' is pointwise at
least as good in every fibre.
\end{proof}

\begin{theorem}[Sharpness]
If $|G|=3$ the Bayes predictor $n\mapsto[n\ne1]$ scores $6$, strictly beating both
constants (which score $5$ and $4$).
\end{theorem}

\begin{corollary}[Positive information, zero advantage]
For every prime $\ell\ge5$ the symmetric divisibility event leaks a strictly positive
number of bits about $N\bmod\ell$, and yet no function of $N\bmod\ell$ predicts it better
than the trivial constant guess.
\end{corollary}

The residue moves the posterior from $2/(\ell-1)$ to $1/(\ell-1)$, but both stay below
$\tfrac12$ for $\ell\ge5$, so the $\arg\max$ never moves: leaked bits that cannot be spent.

\section{Unconditional impossibility}

\begin{theorem}[Swap construction]\label{thm:swap}
For every $\ell>2$ and every modulus $M\ge1$ there exist primes $p_1<q_1<p_2<q_2$ with
\[
p_1q_1\equiv p_2q_2 \pmod M,\qquad \ell\mid p_1-1,\qquad \ell\nmid p_2-1.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Put $Q=\ell M$; then $\gcd(Q-1,Q)=1$, so Dirichlet's theorem supplies infinitely many
primes in each of the classes $1$ and $-1$ modulo $Q$. Choose successively
$p_1\equiv1$, $q_1\equiv-1$, $p_2\equiv-1$, $q_2\equiv1 \pmod Q$ with
$p_1<q_1<p_2<q_2$. Then $p_1q_1\equiv-1\equiv p_2q_2 \pmod Q$, hence modulo $M$; and
$\ell\mid Q$ gives $p_1\equiv1$, $p_2\equiv-1\not\equiv1\pmod\ell$ since $\ell>2$.
\end{proof}

\begin{theorem}[No residue self-hint at any modulus]
For every $\ell>2$ and every $M\ge1$ there is no function $f$ with
$(\ell\mid p-1)\iff f(N\bmod M)$ for all semiprimes $N=pq$, $p<q$.
\end{theorem}

\begin{proof}
The two semiprimes of Theorem~\ref{thm:swap} have equal residues mod $M$ and opposite
secret bits.
\end{proof}

Primality of $\ell$ is not needed and $M$ is arbitrary; the case $M=1155=3\cdot5\cdot7\cdot11$
is the residue tested experimentally. Conceptually: the residue depends only on the
unordered multiset $\{p,q\}$ through its product, while the asymmetric question depends on
the labelling, which multiplication destroys.

\subsection{Three factors}

In a finite group, $\#\{(a,b,c):abc=n,\ a\in A\}=|A|\cdot|G|$ for every $n$, by the
bijection $(a,b,c)\mapsto(a,b)$ onto $A\times G$; the symmetric count varies (over
$(\mathbb Z/3)^\times$ it is $4$ at $n=1$ and $3$ at $n=-1$).

\begin{theorem}
For every $\ell>2$ and every $M\ge1$ no function of $N\bmod M$ decides $\ell\mid p-1$ for
three-factor moduli $N=pqr$ with $p<q<r$.
\end{theorem}

\begin{proof}[Proof sketch]
Extend the swap construction with a third prime $\equiv1\pmod{\ell M}$ in both instances,
preserving the residue collision and the disagreement.
\end{proof}

\subsection{Smoothness itself}

\begin{definition}
$n$ is \emph{$B$-smooth} if every prime divisor of $n$ is at most $B$.
\end{definition}

\begin{theorem}[Completion lemma]
For any modulus $M$ and any $u,v$ coprime to $M$, one can complete $u$ and $v$ to
semiprimes $uu'$ and $vv'$ congruent modulo $M$.
\end{theorem}

\begin{theorem}
No function of $N\bmod 1155$ decides whether $p-1$ is $10$-smooth, for semiprimes $N=pq$
with $p<q$.
\end{theorem}

\begin{theorem}[The $N\pm1$ heuristic fails logically]
All four combinations of the public bit ``$N-1$ is $10$-smooth'' and the secret bit
``$p-1$ is $10$-smooth'' occur, witnessed by $N=253,1081,143,667$. Moreover the full pair
of public bits (``$N-1$ smooth?'', ``$N+1$ smooth?'') is insufficient:
$253=11\cdot23$ and $1081=23\cdot47$ share the pair $(\text{true},\text{false})$ and
disagree on the secret bit.
\end{theorem}

Indeed $253-1=252=2^2\cdot3^2\cdot7$ is $10$-smooth with $p-1=10$ also $10$-smooth, while
$1081-1=1080=2^33^35$ is $10$-smooth with $p-1=22=2\cdot11$ not. The public bits are not
weakly correlated with the secret one; they are logically independent of it.

\section{Tropicalisation}

\begin{theorem}[Fibre transform of a one-sided weight]
Let $G$ be a finite group, $M$ any commutative monoid and $f:G\to M$. Then for every
$n\in G$, $\sum_{ab=n}f(a)=\sum_{a\in G}f(a)$, independent of $n$.
\end{theorem}

\begin{proof}
The projection $(a,b)\mapsto a$ is a bijection from the fibre onto $G$; reindex.
\end{proof}

Taking $M=(\mathbb N,+)$ and $f=\mathbf 1_A$ recovers Theorem~\ref{thm:asym}. Taking $M$ to
be the min-plus (tropical) semiring, where addition is $\min$ and multiplication is $+$:

\begin{corollary}[Tropical asymmetric invariance]
For any cost $f:G\to\mathbb N\cup\{\infty\}$ and every $n$,
$\min_{ab=n}f(a)=\min_{a\in G}f(a)$.
\end{corollary}

\begin{theorem}[Tropical symmetric variance]
The symmetric min-plus statistic $W_f(n)=\min_{ab=n}\max(f(a),f(b))$ does depend on $n$:
for $G=(\mathbb Z/3)^\times$ with $f(1)=1$, $f(-1)=0$, one has $W_f(1)=0$ and $W_f(-1)=1$.
\end{theorem}

The statistic $W_f$ is the tropical shadow of a smoothness profile: it asks for a
factorisation \emph{all of whose factors are cheap}. So the dichotomy is not an artefact of
counting or of Shannon entropy; it is a property of the fibration $\mu:G\times G\to G$
surviving evaluation in any commutative monoid, in particular where cost-optimisation lives.

\section{Agreement with the experimental record}

The theory was developed against a measurement campaign on random $k$-bit semiprimes,
$k\in\{14,16,18\}$, up to $2\times10^5$ samples per size, with $p-1$, $q-1$, $N-1$, $N+1$
fully factored, mutual informations estimated against shuffled-label nulls, and conditional
densities tabulated per residue class.

\begin{enumerate}
\item \textbf{Asymmetric leak $0.0000$--$0.0005$ bits} for $\ell=3,5,7,11$ at every $k$ ---
explained by Theorem~\ref{thm:zeroleak} (exactly zero).
\item \textbf{Symmetric leak $0.313/0.036/0.015/0.005$ bits}, stable in $k$ ---
Theorem~\ref{thm:closed} predicts $0.31128/0.03588/0.01439/0.00484$, and stability is
automatic since the closed form depends only on $\ell$.
\item \textbf{Forcing at $\ell=3$}: $\Pr(\mathrm{OR}\mid N\equiv2)=1.000$ while
$\Pr(p\equiv1\mid N\bmod3)=0.497/0.501$ against base rate $0.499$ ---
Theorems~\ref{thm:force3} and~\ref{thm:asym}.
\item \textbf{Full smoothness undetectable}: $I(S_{1000};N\bmod1155)=0.006$ bits against a
shuffled null of $0.005$ --- no function of $N\bmod1155$ decides smoothness at all, so the
residual is estimator bias.
\item \textbf{No $N\pm1$ self-hint}: correlation $\le0.014$, $I\le0.0001$ --- logical
independence.
\item \textbf{Conditioning-invariant density}: $\Pr[L(p-1)\le B\mid N\equiv n]$ equals the
base rate for every $n$ --- Theorem~\ref{thm:asym} applied to the smoothness target.
\item \textbf{$60$--$78\%$ of these semiprimes are $1000$-weak}, matching an even-adjusted
Dickman baseline to $\approx0.04$: the weak class is large, and still unflaggable.
\end{enumerate}

\section{Discussion}

\subsection{What the dichotomy says}

A product remembers the multiset of its factors and forgets the labels. The fibre of
$\mu:G\times G\to G$ over any $n$ is a free orbit under $a\mapsto(a,a^{-1}n)$, so a
condition on a single coordinate pulls back to a set of $n$-independent size. Conditions
invariant under the coordinate swap survive, and their visibility is exactly an
autocorrelation.

\subsection{Cryptographic reading}

\begin{itemize}
\item \textbf{No weak-key screening.} No residue statistic, at any modulus, flags $p-1$
smoothness; an adversary sorting public keys cannot prioritise.
\item \textbf{Positive leaks may be inert.} The symmetric event leaks measurably, yet for
$\ell\ge5$ confers no prediction advantage; advantage over the best constant strategy is
the operationally meaningful metric.
\item \textbf{Structured targets are the leaky ones.} Quadratic-residue and $k$-th-power
conditions are, in symmetric form, maximally visible (counts $|H|$ versus $2|H|$).
\end{itemize}

\subsection{Barriers}

The results quantify the obstruction that from public data one can access only
swap-invariant functions of the factor pair, with an exact price tag:
$|A\cup nA^{-1}|$ visible factorisations, $(\log_2 e-1)/(\ell-1)^2$ bits leaked
asymptotically, zero prediction advantage above the smallest modulus. Useful hints must
come from genuinely external information.

\section{Future directions}

\begin{enumerate}
\item \textbf{Non-uniform factor distributions.} Chebyshev-type biases perturb the
marginals; the asymmetric leak should remain zero (the bijection argument is
distribution-free once the factors are exchangeable and independent), but the symmetric
leak acquires computable corrections.
\item \textbf{Beyond divisibility atoms.} Full $B$-smoothness corresponds to a target
$A_B\subseteq(\mathbb Z/M)^\times$ that is not a subgroup; computing
$|A_B\cup nA_B^{-1}|$ would give the exact symmetric leak of the smoothness event.
\item \textbf{Sharper asymptotics for general targets.} For $|A|=m$ fixed one expects a
leak of order $m^2/d^2$ with a computable constant; for $|A|\asymp d/2$ the behaviour
should differ.
\item \textbf{Difference-set targets.} Invisibility is exactly the perfect-difference-set
condition, impossible nontrivially in abelian groups; the nonabelian classification is a
clean combinatorial problem.
\item \textbf{Tropical smoothness profiles.} The distribution of
$W_f(n)=\min_{ab=n}\max(f(a),f(b))$, for costs modelling largest-prime-factor size, is a
min-plus analogue of the Dickman function.
\end{enumerate}

\section{Conclusion}

Can a semiprime betray that it is $p-1$-weak? No: not through a residue at any modulus,
not through the smoothness of $N\pm1$, not through any statistic of the public data, and
not for two- or three-factor moduli. Multiplication destroys the labelling of factors, so
every one-sided condition has an $n$-independent fibre count and exactly zero mutual
information with the product.

What survives is the symmetric shadow, and it is completely understood: count
$|A\cup nA^{-1}|$; vanishing leak exactly for perfect difference sets, hence never
nontrivially in abelian groups; value $I(\ell-1)$, equal to $0.311$ bits at $\ell=3$ and
decaying like $(\log_2 e-1)/(\ell-1)^2$; and zero prediction advantage for $\ell\ge5$. The
same dichotomy reads verbatim in the min-plus semiring, where the symmetric statistic
becomes the cost of the cheapest factorisation all of whose factors are cheap.

Weakness is common. Weakness is invisible. Both facts are now theorems.

