"""
Fibre-count evaluation for one-sided and two-sided factorisation predicates.

Given a prime modulus l, a target set A inside G = (Z/l)^*, and a residue n,
compute

    asym(n) = #{ (a,b) in G x G : a*b = n,  a in A }
    sym(n)  = #{ (a,b) in G x G : a*b = n,  a in A or b in A }

The naive method scans the whole fibre: O(|G|) modular inverses per residue, so
O(|G|^2) for the whole profile.  The structural method uses the two theorems

    asym(n) = |A|                       (independent of n)
    sym(n)  = |A u n A^{-1}| = 2|A| - |A n n A^{-1}|

which costs O(|A|) hash operations per residue after one O(|A|) inversion pass,
i.e. O(|G| |A|) overall and O(1) for the asymmetric profile.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Set, Tuple


def units(ell: int) -> List[int]:
    """The multiplicative group G = (Z/l)^*."""
    return [a for a in range(1, ell) if gcd(a, ell) == 1]


def naive_profile(ell: int, target: Set[int]) -> Dict[int, Tuple[int, int]]:
    """Brute-force fibre profile.  Cost: O(|G|^2) modular operations."""
    group: List[int] = units(ell)
    out: Dict[int, Tuple[int, int]] = {}
    for n in group:
        asym = 0
        sym = 0
        for a in group:
            b = (pow(a, -1, ell) * n) % ell
            if a in target:
                asym += 1
            if a in target or b in target:
                sym += 1
        out[n] = (asym, sym)
    return out


def structural_profile(ell: int, target: Set[int]) -> Dict[int, Tuple[int, int]]:
    """
    Structural fibre profile via the counting theorems.
    Cost: O(|A|) inversions once, then O(|A|) per residue.
    """
    group: List[int] = units(ell)
    inverses: Dict[int, int] = {a: pow(a, -1, ell) for a in target}
    size: int = len(target)
    out: Dict[int, Tuple[int, int]] = {}
    for n in group:
        reflected: Set[int] = {n * inverses[a] % ell for a in target}
        overlap: int = len(target & reflected)          # the autocorrelation
        out[n] = (size, 2 * size - overlap)
    return out


def autocorrelation(ell: int, target: Set[int]) -> Dict[int, int]:
    """n |-> |A n n A^{-1}|, the statistic that decides visibility."""
    inverses: Dict[int, int] = {a: pow(a, -1, ell) for a in target}
    return {
        n: len(target & {n * inverses[a] % ell for a in target})
        for n in units(ell)
    }


def symmetric_leak_is_zero(ell: int, target: Set[int]) -> bool:
    """The classification criterion: constant autocorrelation."""
    values = set(autocorrelation(ell, target).values())
    return len(values) <= 1


if __name__ == "__main__":
    for ell in (3, 5, 7, 11, 13, 17):
        for name, A in (
            ("A = {1}", {1}),
            ("A = quadratic residues", {a * a % ell for a in units(ell)}),
            ("A = G", set(units(ell))),
        ):
            naive = naive_profile(ell, A)
            fast = structural_profile(ell, A)
            assert naive == fast, (ell, name)
            asym_vals = sorted({v[0] for v in fast.values()})
            sym_vals = sorted({v[1] for v in fast.values()})
            print(f"l={ell:3d}  {name:24s}  asym counts {asym_vals}  "
                  f"sym counts {sym_vals}  invisible: {symmetric_leak_is_zero(ell, A)}")
